507	    /**
508	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
509	     * Returns the actual amount debited (0 if no balance available).
510	     */
511	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode): int
512	    {
513	        if ($requestedCents <= 0) {
514	            return 0;
515	        }
516	
517	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode) {
518	            $brand = Professional::query()
519	                ->whereKey($brandId)
520	                ->lockForUpdate()
521	                ->first();
522	
523	            if (! $brand) {
524	                return 0;
525	            }
526	
527	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
528	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
529	
530	            if ($walletCurrency !== strtoupper($currencyCode) || $balance <= 0) {
531	                return 0;
532	            }
533	
534	            $debit = min($balance, $requestedCents);
535	            $brand->stripe_manual_balance_cents = $balance - $debit;
536	            $brand->save();
537	
538	            return $debit;
539	        });
540	    }
