565	    private function extractLatestChargeId(object $paymentIntent): ?string
566	    {
567	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
568	            return $paymentIntent->latest_charge;
569	        }
570	
571	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
572	            return $paymentIntent->latest_charge->id;
573	        }
574	
575	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
576	            foreach ($paymentIntent->charges->data as $charge) {
577	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
578	                    return $charge->id;
579	                }
580	            }
581	        }
582	
583	        return null;
584	    }
