655	    /**
656	     * Get payout summary for a professional (as brand or affiliate).
657	     */
658	    public function getPayoutSummary(Professional $professional): array
659	    {
660	        $asBrand = CommissionPayout::query()
661	            ->where('brand_professional_id', $professional->id)
662	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
663	            ->groupBy('status')
664	            ->get()
665	            ->keyBy('status');
666	
667	        $asAffiliate = CommissionPayout::query()
668	            ->where('affiliate_professional_id', $professional->id)
669	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
670	            ->groupBy('status')
671	            ->get()
672	            ->keyBy('status');
673	
674	        return [
675	            'as_brand' => $asBrand,
676	            'as_affiliate' => $asAffiliate,
677	        ];
678	    }
